  1	import { useCallback, useEffect, useRef, useState, type FormEvent, type KeyboardEvent } from "react";
  2	
  3	import type { ApiClient } from "../auth/api";
  4	import { archiveCalendar, createCalendar, deleteCalendar as deleteCalendarRequest, IcsImportApiError, importIcs, isCalendarAccessChange, listCalendarAcl, listCalendars, restoreCalendar, revokeCalendarAcl, setCalendarAcl, transferCalendarOwnership, updateCalendar, type CalendarAclEntry, type IcsImportSummary, type ShareableCalendarRole } from "./api";
  5	import "./CalendarManagement.css";
  6	
  7	export type CalendarRole = "owner" | "manager" | "editor" | "viewer" | "free_busy_viewer";
  8	
  9	export interface Calendar {
 10	  id: number;
 11	  access: "details" | "free_busy";
 12	  role: CalendarRole;
 13	  owner_user_id?: number;
 14	  name?: string;
 15	  description?: string | null;
 16	  color?: string;
 17	  default_timezone?: string;
 18	  default_event_visibility?: string;
 19	  default_notification_rules_json?: string | null;
 20	  archived?: boolean;
 21	  version?: number;
 22	}
 23	
 24	interface CalendarSettings {
 25	  name: string;
 26	  description: string;
 27	  color: string;
 28	  default_timezone: string;
 29	  default_event_visibility: string;
 30	}
 31	
 32	const blankSettings: CalendarSettings = {
 33	  name: "", description: "", color: "#3b82f6", default_timezone: "UTC", default_event_visibility: "private",
 34	};
 35	
 36	function settingsFor(calendar?: Calendar): CalendarSettings {
 37	  return calendar === undefined ? blankSettings : {
 38	    name: calendar.name ?? "", description: calendar.description ?? "", color: calendar.color ?? "#3b82f6",
 39	    default_timezone: calendar.default_timezone ?? "UTC", default_event_visibility: calendar.default_event_visibility ?? "private",
 40	  };
 41	}
 42	
 43	function payload(settings: CalendarSettings) {
 44	  return { ...settings, description: settings.description || null, default_notification_rules_json: null };
 45	}
 46	
 47	function canManage(calendar: Calendar) {
 48	  return calendar.access === "details" && (calendar.role === "owner" || calendar.role === "manager");
 49	}
 50	
 51	function canCreateEvents(calendar: Calendar) {
 52	  return calendar.access === "details" && (calendar.role === "owner" || calendar.role === "manager" || calendar.role === "editor");
 53	}
 54	
 55	function canDelete(calendar: Calendar) {
 56	  return calendar.access === "details" && calendar.role === "owner";
 57	}
 58	
 59	const shareableRoles: { value: ShareableCalendarRole; label: string }[] = [
 60	  { value: "manager", label: "Manager" }, { value: "editor", label: "Editor" }, { value: "viewer", label: "Viewer" }, { value: "free_busy_viewer", label: "Free/busy viewer" },
 61	];
 62	
 63	const CALENDAR_COLORS = [
 64	  "#ef4444", "#f97316", "#f59e0b", "#10b981", "#3b82f6",
 65	  "#8b5cf6", "#ec4899", "#06b6d4", "#84cc16", "#f43f5e",
 66	];
 67	
 68	function initialsFor(email: string): string {
 69	  const parts = email.split("@")[0].split(/[._-]/);
 70	  if (parts.length >= 2) return (parts[0][0] + parts[parts.length - 1][0]).toUpperCase();
 71	  return email.slice(0, 2).toUpperCase();
 72	}
 73	
 74	function roleLabel(role: string): string {
 75	  return role === "owner" ? "Owner" : role.replaceAll("_", " ").replace(/\b\w/g, (c) => c.toUpperCase());
 76	}
 77	
 78	// eslint-disable-next-line @typescript-eslint/no-unused-vars
 79	function SharingDialog({ api, calendar, onClose, onCalendarChanged, onAccessDenied, triggerEl }: { api: ApiClient; calendar: Calendar; onClose: () => void; onCalendarChanged: (calendar: Calendar) => void; onAccessDenied: () => void; triggerEl: HTMLButtonElement | null }) {
 80	  const [entries, setEntries] = useState<CalendarAclEntry[]>([]);
 81	  const [error, setError] = useState<string | null>(null);
 82	  const [userId, setUserId] = useState("");
 83	  const [newRole, setNewRole] = useState<ShareableCalendarRole>("viewer");
 84	  const [roleEdits, setRoleEdits] = useState<Record<number, ShareableCalendarRole>>({});
 85	  const [transferTarget, setTransferTarget] = useState<number | null>(null);
 86	  const closeButton = useRef<HTMLButtonElement>(null);
 87	
 88	  useEffect(() => {
 89	    closeButton.current?.focus();
 90	  }, []);
 91	
 92	  useEffect(() => {
 93	    let active = true;
 94	    void listCalendarAcl(api, calendar.id).then((result) => { if (active) setEntries(result); }).catch((reason: unknown) => {
 95	      if (!active) return;
 96	      if (isCalendarAccessChange(reason)) onAccessDenied();
 97	      else setError("We could not load collaborators.");
 98	    });
 99	    return () => { active = false; };
100	  }, [api, calendar.id, onAccessDenied]);
101	
102	  useEffect(() => {
103	    const dialog = closeButton.current?.closest("[role=\"dialog\"]");
104	    if (!dialog) return;
105	    const handler = (e: Event) => {
106	      const keyboardEvent = e as unknown as KeyboardEvent;
107	      if (keyboardEvent.key === "Escape") {
108	        keyboardEvent.preventDefault();
109	        if (transferTarget !== null) setTransferTarget(null);
110	        else onClose();
111	      }
112	    };
113	    dialog.addEventListener("keydown", handler);
114	    return () => { dialog.removeEventListener("keydown", handler); };
115	  }, [transferTarget]);
116	
117	  async function saveRole(entryUserId: number, role: ShareableCalendarRole) {
118	    setError(null);
119	    try {
120	      const updated = await setCalendarAcl(api, calendar.id, entryUserId, role);
121	      setEntries((current) => current.some((entry) => entry.user_id === entryUserId) ? current.map((entry) => entry.user_id === entryUserId ? updated : entry) : [...current, updated]);
122	      setRoleEdits((current) => ({ ...current, [entryUserId]: updated.role as ShareableCalendarRole }));
123	    } catch (reason) { if (isCalendarAccessChange(reason)) onAccessDenied(); else setError("We could not save this collaborator's role."); }
124	  }
125	
126	  async function revoke(entryUserId: number) {
127	    setError(null);
128	    try { await revokeCalendarAcl(api, calendar.id, entryUserId); setEntries((current) => current.filter((entry) => entry.user_id !== entryUserId)); }
129	    catch (reason) { if (isCalendarAccessChange(reason)) onAccessDenied(); else setError("We could not revoke this collaborator's access."); }
130	  }
131	
132	  async function transfer() {
133	    if (transferTarget === null || calendar.version === undefined) return;
134	    setError(null);
135	    try {
136	      const updated = await transferCalendarOwnership(api, calendar.id, transferTarget, calendar.version);
137	      onCalendarChanged(updated);
138	      onClose();
139	    } catch (reason) { if (isCalendarAccessChange(reason)) onAccessDenied(); else setError("We could not transfer ownership."); }
140	  }
141	
142	  const ownerEntry = entries.find((e) => e.role === "owner");
143	  const nonOwnerEntries = entries.filter((e) => e.role !== "owner");
144	
145	  return <div className="sharing-dialog" role="dialog" aria-modal="true" aria-labelledby="sharing-heading">
146	    <div className="sharing-dialog__card">
147	      <div className="sharing-dialog__header">
148	        <h3 id="sharing-heading">Share {calendar.name ?? "calendar"}</h3>
149	        <button ref={closeButton} className="sharing-dialog__close" type="button" onClick={onClose} aria-label="Close sharing">
150	          <span className="material-symbols-outlined">close</span>
151	        </button>
152	      </div>
153	      <div className="sharing-dialog__body">
154	        {error && <p className="sharing-dialog__error" role="alert">{error}</p>}
155	        <div className="sharing-dialog__invite">
156	          <h4 className="sharing-dialog__invite-title">Invite Collaborators</h4>
157	          <form className="sharing-dialog__invite-row" onSubmit={(event) => { event.preventDefault(); const id = Number(userId); if (!Number.isInteger(id) || id <= 0) { setError("Enter a valid user ID."); return; } void saveRole(id, newRole); }}>
158	            <div className="sharing-dialog__invite-input-wrapper">
159	              <span className="material-symbols-outlined">person_add</span>
160	              <input className="sharing-dialog__invite-input" type="number" min="1" placeholder="Enter User ID" aria-label="User ID" required value={userId} onChange={(event) => setUserId(event.target.value)} />
161	            </div>
162	            <select className="sharing-dialog__invite-select" aria-label="Role" value={newRole} onChange={(event) => setNewRole(event.target.value as ShareableCalendarRole)}>
163	              {shareableRoles.map((role) => <option key={role.value} value={role.value}>{role.label}</option>)}
164	            </select>
165	            <button className="sharing-dialog__send-btn" type="submit">Send Invite</button>
166	          </form>
167	        </div>
168	        <div>
169	          <h4 className="sharing-dialog__collaborators-title">Current Collaborators</h4>
170	          <ul className="sharing-dialog__collaborator-list">
171	            {ownerEntry && <li className="sharing-dialog__owner-row">
172	              <div className="sharing-dialog__collab-info">
173	                <div className="sharing-dialog__avatar sharing-dialog__avatar--owner">{initialsFor(calendar.name ?? "ME")}</div>
174	                <div className="sharing-dialog__collab-details">
175	                  <div className="sharing-dialog__collab-name">{ownerEntry.user_id}</div>
176	                  <div className="sharing-dialog__collab-role"><span className="dot" />Owner</div>
177	                </div>
178	              </div>
179	              {nonOwnerEntries.length > 0 && transferTarget === null &&
180	                <button className="sharing-dialog__transfer-btn" type="button" onClick={() => setTransferTarget(nonOwnerEntries.find((e) => e.role !== "owner")?.user_id ?? null)}>
181	                  <span className="material-symbols-outlined">swap_horiz</span> Transfer ownership
182	                </button>
183	              }
184	              {transferTarget !== null && <div className="sharing-dialog__confirm" role="dialog" aria-modal="true" aria-labelledby="transfer-confirmation-heading">
185	                <h4 id="transfer-confirmation-heading">Confirm ownership transfer</h4>
186	                <p>User {transferTarget} will become the owner. You will become a manager.</p>
187	                <div className="sharing-dialog__confirm-actions">
188	                  <button className="btn-discard" type="button" onClick={() => setTransferTarget(null)}>Cancel</button>
189	                  <button className="btn-confirm" type="button" onClick={() => void transfer()}>Confirm transfer</button>
190	                </div>
191	              </div>}
192	            </li>}
193	            {nonOwnerEntries.map((entry) => <li key={entry.user_id} className="sharing-dialog__collaborator">
194	              <div className="sharing-dialog__collab-info">
195	                <div className="sharing-dialog__avatar">{initialsFor(String(entry.user_id))}</div>
196	                <div className="sharing-dialog__collab-details">
197	                  <div className="sharing-dialog__collab-name">User {entry.user_id}</div>
198	                  <div className="sharing-dialog__collab-role sharing-dialog__collab-role--primary">{roleLabel(entry.role)}</div>
199	                </div>
200	              </div>
201	              <div className="sharing-dialog__collab-actions">
202	                <label className="sharing-dialog__role-label">Role for user {entry.user_id}
203	                  <select className="sharing-dialog__role-select" value={roleEdits[entry.user_id] ?? entry.role} onChange={(event) => setRoleEdits((current) => ({ ...current, [entry.user_id]: event.target.value as ShareableCalendarRole }))}>
204	                    {shareableRoles.map((role) => <option key={role.value} value={role.value}>{role.label}</option>)}
205	                  </select>
206	                </label>
207	                <button className="sharing-dialog__icon-btn" type="button" onClick={() => void saveRole(entry.user_id, roleEdits[entry.user_id] ?? entry.role)} aria-label={`Save role for user ${entry.user_id}`}>
208	                  <span className="material-symbols-outlined">save</span>
209	                </button>
210	                <button className="sharing-dialog__icon-btn sharing-dialog__icon-btn--danger" type="button" onClick={() => void revoke(entry.user_id)} aria-label={`Revoke access for user ${entry.user_id}`}>
211	                  <span className="material-symbols-outlined">person_remove</span>
212	                </button>
213	              </div>
214	            </li>)}
215	          </ul>
216	        </div>
217	      </div>
218	      <div className="sharing-dialog__footer">
219	        <button className="btn-cancel" type="button" onClick={onClose}>Cancel</button>
220	        <button className="btn-primary" type="button" onClick={onClose}>Done</button>
221	      </div>
222	    </div>
223	  </div>;
224	}
