226	function ColorSwatchPicker({ value, onChange }: { value: string; onChange: (color: string) => void }) {
227	  return <div className="color-swatches-picker" role="radiogroup" aria-label="Theme color">
228	    {CALENDAR_COLORS.map((color) =>
229	      <button key={color} type="button" className={`color-swatch-picker${value === color ? " color-swatch-picker--active" : ""}`}
230	        style={{ background: color }} aria-pressed={value === color} role="radio"
231	        aria-label={`Color ${color}`} tabIndex={value === color ? 0 : -1}
232	        onClick={() => onChange(color)} />
233	    )}
234	  </div>;
235	}
236	
237	function CalendarFormModal({ editing, settings, setSettings, onSave, onCancel, submitting }: {
238	  editing: Calendar | null;
239	  settings: CalendarSettings;
240	  setSettings: (s: CalendarSettings) => void;
241	  onSave: (event: FormEvent<HTMLFormElement>) => void;
242	  onCancel: () => void;
243	  submitting: boolean;
244	}) {
245	  const title = editing === null ? "New Calendar" : "Edit Calendar";
246	  return <div className="calendar-modal-overlay" onClick={onCancel}>
247	    <div className="calendar-modal" onClick={(e) => e.stopPropagation()} role="dialog" aria-modal="true" aria-labelledby="modal-heading">
248	      <div className="calendar-modal__header">
249	        <h3 id="modal-heading">{title}</h3>
250	        <button className="calendar-modal__close" type="button" onClick={onCancel} aria-label="Close">
251	          <span className="material-symbols-outlined" aria-hidden="true">close</span>
252	        </button>
253	      </div>
254	      <form className="calendar-form" onSubmit={onSave} aria-label={editing === null ? "Create calendar" : `Edit ${editing.name ?? "calendar"}`}>
255	        <div className="calendar-modal__body">
256	          <label>Calendar name
257	            <input required value={settings.name} onChange={(event) => setSettings({ ...settings, name: event.target.value })} placeholder="e.g., Team Syncs" />
258	          </label>
259	          <label>Description <span className="optional">(Optional)</span>
260	            <textarea value={settings.description} onChange={(event) => setSettings({ ...settings, description: event.target.value })} placeholder="What is this calendar for?" rows={3} />
261	          </label>
262	          <label>Theme Color
263	            <ColorSwatchPicker value={settings.color} onChange={(color) => setSettings({ ...settings, color })} />
264	          </label>
265	          <div className="calendar-modal__grid">
266	            <label>Timezone
267	              <select value={settings.default_timezone} onChange={(event) => setSettings({ ...settings, default_timezone: event.target.value })}>
268	                <option>Pacific Time (PT)</option>
269	                <option>Eastern Time (ET)</option>
270	                <option>UTC</option>
271	              </select>
272	            </label>
273	            <label>Visibility
274	              <select value={settings.default_event_visibility} onChange={(event) => setSettings({ ...settings, default_event_visibility: event.target.value })}>
275	                <option value="private">Private</option>
276	                <option value="default">Default</option>
277	                <option value="public">Public</option>
278	              </select>
279	            </label>
280	          </div>
281	        </div>
